using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Reflection;using System.Diagnostics;using System.Text.RegularExpressions;using System.Web.Script.Serialization;
namespace SplifyWin {
 public sealed class AppModule {public int Format{get;set;}public string Version{get;set;}public string Hash{get;set;}public long Size{get;set;}public string File{get;set;}public RuntimeManifest Runtime{get;set;}}
 public static class AppRuntime {
  public const string PackageName="mcrf-app-update.zip";public const string ThinMarker="Mcrf.Runtime.Thin";
  public static string Profile(string[] args){return Path.GetFullPath(args.Length>1&&args[0]=="--data"?args[1]:Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"mcrf-wpf"));}
  static string Pointer(string root){return Path.Combine(root,"runtime","active-app.json");}
  static Version assemblyVersion(){return Assembly.GetExecutingAssembly().GetName().Version;}
  static string Quote(string value){if(value==null||value.IndexOfAny(new[]{'"','\r','\n'})>=0)throw new InvalidDataException("Некорректный путь запуска");return "\""+value+"\"";}
  public static AppModule ReadModule(string text){var m=new JavaScriptSerializer().Deserialize<AppModule>(text);if(m==null||m.Format!=1||!Regex.IsMatch(m.Hash??"",@"^[a-f0-9]{64}$")||m.Size<128||m.Size>16777216||String.IsNullOrWhiteSpace(m.Version))throw new InvalidDataException("Некорректный пакет программы");RuntimeResources.Read(new JavaScriptSerializer().Serialize(m.Runtime));return m;}
  public static AppModule Extract(string archive,string dir){using(var zip=ZipFile.OpenRead(archive)){if(zip.Entries.Count!=2||zip.Entries.Any(e=>e.FullName!="mcrf.exe"&&e.FullName!="module.json")||zip.Entries.Select(e=>e.FullName).Distinct().Count()!=2)throw new InvalidDataException("Неожиданный состав пакета программы");var metadata=zip.GetEntry("module.json");if(metadata.Length>100000)throw new InvalidDataException("Слишком большой каталог программы");AppModule m;using(var r=new StreamReader(metadata.Open()))m=ReadModule(r.ReadToEnd());var exe=zip.GetEntry("mcrf.exe");if(exe.Length!=m.Size)throw new InvalidDataException("Размер программы не совпал");m.File=Path.Combine(dir,"mcrf.exe");exe.ExtractToFile(m.File);if(RuntimeResources.HashFile(m.File)!=m.Hash)throw new InvalidDataException("SHA-256 программы не совпал");var info=AssemblyName.GetAssemblyName(m.File);if(info.Version.ToString(3)!=m.Version)throw new InvalidDataException("Версия программы не совпала");File.WriteAllText(Path.Combine(dir,"module.json"),new JavaScriptSerializer().Serialize(m));return m;}}
  static void Validate(string root,AppModule m){ReadModule(new JavaScriptSerializer().Serialize(m));string prefix=Path.GetFullPath(Path.Combine(root,"updates","installed"))+Path.DirectorySeparatorChar;if(!Path.GetFullPath(m.File??"").StartsWith(prefix,StringComparison.OrdinalIgnoreCase)||!File.Exists(m.File)||new FileInfo(m.File).Length!=m.Size||RuntimeResources.HashFile(m.File)!=m.Hash)throw new InvalidDataException("Повреждена установленная программа");foreach(var r in m.Runtime.Resources)if(!RuntimeResources.Present(root,r))throw new InvalidDataException("Не установлен компонент "+r.Name);}
  public static void Activate(string root,AppModule m){Validate(root,m);string path=Pointer(root);Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,new JavaScriptSerializer().Serialize(m));if(File.Exists(path))File.Replace(temp,path,path+".previous",true);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
  public static void Restart(string root){string launcher=Environment.GetEnvironmentVariable("MCRF_BOOTSTRAP_EXE");if(String.IsNullOrEmpty(launcher))launcher=Assembly.GetExecutingAssembly().Location;using(var parent=Process.GetCurrentProcess())Process.Start(new ProcessStartInfo(launcher,"--data "+Quote(root)+" --restart-after "+parent.Id+" "+parent.StartTime.ToUniversalTime().Ticks+" --interactive"){UseShellExecute=false,CreateNoWindow=true});}
  public static bool Bootstrap(string[] args){string root=Profile(args);int restart=Array.IndexOf(args,"--restart-after");if(restart>=0){if(args.Length<restart+3)throw new InvalidDataException("Неверный запрос перезапуска");int pid;long ticks;if(!Int32.TryParse(args[restart+1],out pid)||!Int64.TryParse(args[restart+2],out ticks))throw new InvalidDataException("Неверный запрос перезапуска");try{using(var parent=Process.GetProcessById(pid)){if(parent.StartTime.ToUniversalTime().Ticks!=ticks||!parent.WaitForExit(30000))throw new IOException("Не удалось дождаться завершения MCRF");}}catch(ArgumentException){}}
   string path=Pointer(root);if(!File.Exists(path))return false;AppModule module=null;try{module=ReadModule(File.ReadAllText(path));Version installed;if(Version.TryParse(module.Version,out installed)&&installed<assemblyVersion())return false;Validate(root,module);if(Path.GetFullPath(module.File).Equals(Assembly.GetExecutingAssembly().Location,StringComparison.OrdinalIgnoreCase))return false;var psi=new ProcessStartInfo(module.File,"--data "+Quote(root)+(args.Length==0||args.Contains("--interactive")?" --interactive":"")){UseShellExecute=false,CreateNoWindow=true};string launcher=Environment.GetEnvironmentVariable("MCRF_BOOTSTRAP_EXE")??Assembly.GetExecutingAssembly().Location;psi.EnvironmentVariables["MCRF_BOOTSTRAP_EXE"]=launcher;using(var child=Process.Start(psi)){if(!child.WaitForExit(8000)||child.ExitCode==0)return true;}throw new IOException("Новая версия не запустилась");
   }catch(Exception error){try{File.AppendAllText(Path.Combine(root,"update-startup.log"),DateTime.UtcNow.ToString("o")+" "+error.GetType().Name+Environment.NewLine);}catch{}if(File.Exists(path+".previous")){File.Copy(path+".previous",path,true);try{var old=ReadModule(File.ReadAllText(path));Validate(root,old);if(module!=null&&String.Equals(old.File,module.File,StringComparison.OrdinalIgnoreCase))return false;return Bootstrap(new[]{"--data",root});}catch{}}return false;}
  }
 }
}
